1125	template <typename Dims, typename ParamT, typename GradT>
1126	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
1127	sg2_meta_optimizer_megakernel(
1128	    PersistentContext ctx,
1129	    SG2Weights w,
1130	    SG2State st,
1131	    SG2Scalars sc,
1132	    ParamT* __restrict__ params,
1133	    const GradT* __restrict__ grads,
1134	    const float* __restrict__ sharpness) {
1135	    // Stage the (small) weight bundle into shared memory once per CTA.
1136	    __shared__ SG2SmemWeights<Dims> sw;
1137	    sg2_stage_weights<Dims>(sw, w);
1138	    __syncthreads();
1139	
1140	    GridBarrier bar = ctx.barrier();
1141	    float* my_ws = st.workspace + (int64_t)blockIdx.x * st.ws_stride;
1142	
1143	    // Work-steal WHOLE tensors. Each tensor's full pipeline is CTA-local.
1144	    __shared__ int task_slot;
1145	    TaskQueue q = ctx.queue();
1146	    for (int t = q.next_block(&task_slot); t < st.n_tensors;
1147	         t = q.next_block(&task_slot)) {
1148	        sg2_meta_stages<Dims, ParamT, GradT>(
1149	            sw, t, st, sc, params, grads, sharpness, my_ws);
1150	    }
1151	
1152	    // ONE grid barrier: lets a composing model stage reset the queue after the
1153	    // optimizer tail drains. (Standalone, this is just a clean exit fence.)
1154	    bar.sync();
1155	}
